test("accepts only generated UUID v4 correlation identifiers", () => {
  assert.throws(
    () =>
      createAppPerformanceEvent({
        routeGroup: "routine",
        operation: "proxy_access",
        outcome: "success",
        durationMs: 1,
        correlationId: "request-correlation-id",
      }),
    /correlationId/,
  )
})

